{"command":"cd /work/documents && (command -v pdftotext && pdftotext extrato_maio_2026.pdf - ) || python3 - <<'EOF'
import re,zlib
data=open('extrato_maio_2026.pdf','rb').read()
print(len(data))
# find stream objects
for m in re.finditer(rb'stream\r?\n(.*?)endstream', data, re.S):
    s=m.group(1)
    try:
        t=zlib.decompress(s)
        txt=re.findall(rb'\((.*?)\)\s*Tj|\[(.*?)\]\s*TJ', t, re.S)
        if txt:
            print('---stream---')
            print(t[:4000].decode('latin-1')[:4000])
    except Exception as e:
        pass
EOF"}

